// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Context.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";

contract CryptoPigsGame is Context, Ownable {

    constructor(uint tickPeriod) {
        _setTickPeriod(tickPeriod);
    }

    mapping(address => bool) _canEdit;

    IERC721 Piggies;

    uint _tickPeriod;

    struct Decay {
        int perTick;
        uint blockLastAccountedFor;
    }

    struct Boost {
        string name;
        int perTick;
        uint blockLastAccountedFor;
        uint endsAt;
    }

    struct Attribute {
        int value;
        Decay decay;
        Boost[] boosts;
    }

    struct Pig {
        mapping(string => Attribute) attributes;
    }

    mapping(uint => Pig) _pigs;

    function getTickPeriod() public view returns(uint) {
        return _tickPeriod;
    }
    function getAttributeValueOfPig(uint pigId, string calldata attributeName) public view returns(int) {
        return _getAttributeValue(_getPig(pigId).attributes[attributeName]);
    }
    function getActiveBoostsOfAttributeOfPig(uint pigId, string calldata attributeName) public view returns(Boost[] memory) {
        return _getPig(pigId).attributes[attributeName].boosts;
    }
    function getDecayOfAttributeOfPig(uint pigId, string calldata attributeName) public view returns(Decay memory) {
        return _getPig(pigId).attributes[attributeName].decay;
    }

    function setApprovalOfAddressToEdit(address addr, bool approval) public onlyOwner {
        _setApprovalOfAddressToEdit(addr, approval);
    }

    function addToAttributeOfPig(uint pigId, string calldata attributeName, int value) public onlyApproved {
        _addToAttribute(_getPig(pigId).attributes[attributeName], value);
    }
    function addBoostToAttributeOfPig(uint pigId, string calldata attributeName, string calldata boostName, int perTick, uint blocks) public onlyApproved {
        _addBoostToAttribute(_getPig(pigId).attributes[attributeName], boostName, perTick, blocks);
    }
    function modifyDecayOfAttribute(uint pigId, string calldata attributeName, int value) public onlyApproved {
        _modifyDecayOfAttribute(_getPig(pigId).attributes[attributeName], value);
    }

    function clearAttributeOfPig(uint pigId, string calldata attributeName) public onlyApproved {
        _clearAttribute(_getPig(pigId).attributes[attributeName]);
    }




    function _getPig(uint pigId) private view returns(Pig storage) {
        return _pigs[pigId];
    }
    function _addToAttribute(Attribute storage attribute, int value) private {
        attribute.value += value;
    }
    function _getAttributeValue(Attribute storage attribute) private view returns(int value) {
        value = attribute.value;
        value += _getDecayEffect(attribute.decay);
        for(uint i; i < attribute.boosts.length; i ++) {
            value += _getBoostEffect(attribute.boosts[i]);
        }
    }
    function _getDecayEffect(Decay storage decay) private view returns(int) {
        uint effectiveBlocks = _blkNumber() - decay.blockLastAccountedFor;
        uint ticks = _ticksFor(effectiveBlocks);
        return int(ticks) * decay.perTick;
    }
    function _getBoostEffect(Boost storage boost) private view returns(int) {
        uint blkNumber = _blkNumber();
        uint lastEffectiveBlock = blkNumber <= boost.endsAt ? blkNumber : boost.endsAt;
        uint effectiveBlocks = lastEffectiveBlock - boost.blockLastAccountedFor;
        uint ticks = _ticksFor(effectiveBlocks);
        return int(ticks) * boost.perTick;
    }
    function _accountForDecayOfAttribute(Attribute storage attribute) private {
        int decayEffect = _getDecayEffect(attribute.decay);
        attribute.value += decayEffect;
        attribute.decay.blockLastAccountedFor = _blkNumber();
    }
    function _accountForBoostsOfAttribute(Attribute storage attribute) private {
        uint blkNumber = _blkNumber();
        uint i;
        while(i < attribute.boosts.length) {
            int boostEffect = _getBoostEffect(attribute.boosts[i]);
            attribute.value += boostEffect;
            attribute.boosts[i].blockLastAccountedFor = blkNumber;
            if(blkNumber >= attribute.boosts[i].endsAt) {
                for(uint j = i + 1; j < attribute.boosts.length; j ++) {
                    attribute.boosts[j - 1] = attribute.boosts[j];
                }
                attribute.boosts.pop();
            } else {
                i ++;
            }
        }
    }
    function _modifyDecayOfAttribute(Attribute storage attribute, int value) private {
        _accountForDecayOfAttribute(attribute);
        attribute.decay.perTick += value;
    }
    function _addBoostToAttribute(Attribute storage attribute, string calldata boostName, int perTick, uint blocks) private {
        uint blkNumber = _blkNumber();
        _accountForBoostsOfAttribute(attribute);
        attribute.boosts.push(Boost(boostName, perTick, blkNumber, blkNumber + blocks));
    }
    function _clearAttribute(Attribute storage attribute) private {
        delete attribute.boosts;
        delete attribute.decay;
        delete attribute.value;
    }
    function _ticksFor(uint blocks) private view returns(uint) {
        return blocks / _tickPeriod;
    }
    function _blkNumber() private view returns(uint) {
        return block.number;
    }

    function _setApprovalOfAddressToEdit(address addr, bool approval) private {
        _canEdit[addr] = approval;
    }

    modifier onlyApproved() {
        require(_canEdit[_msgSender()], "Not approved to edit pig attributes.");
        _;
    }

    function _setTickPeriod(uint tickPeriod) private {
        _tickPeriod = tickPeriod;
    }
}
